
<?php

/**
 * Delete a lesson upload only when it is inside uploads/lessons
 * and has a filename generated by the lesson upload API.
 */
function lessonServiceDeleteFile(?string $relativePath): void
{
    if (!$relativePath) {
        return;
    }

    $relativePath = str_replace('\\', '/', $relativePath);

    if (!preg_match(
        '~^uploads/lessons/[a-f0-9]{32}\.(?:pdf|ppt|pptx)$~i',
        $relativePath
    )) {
        return;
    }

    $root = realpath(dirname(__DIR__));
    $file = realpath(dirname(__DIR__) . '/' . $relativePath);

    if (
        $root !== false &&
        $file !== false &&
        is_file($file) &&
        str_starts_with($file, $root . DIRECTORY_SEPARATOR)
    ) {
        if (!@unlink($file)) {
            error_log('Could not delete lesson upload: ' . $relativePath);
        }
    }
}
